def dehydrate_time(value):
    """ Dehydrator for `time` values.

    :param value:
    :type value: Time
    :return:
    """
    if value is None:
        return None

    # If the value is already a string, assume it's correct
    if isinstance(value, str):
        return value

    # Try to build a HH:MM:SS representation from common attributes
    try:
        hour = getattr(value, "hour", None)
        minute = getattr(value, "minute", None)
        second = getattr(value, "second", None)
        if hour is not None and minute is not None and second is not None:
            return f"{int(hour):02}:{int(minute):02}:{int(second):02}"
    except Exception:
        # Fall through to fallback logic
        pass

    # If the value has a ``to_iso_string`` method (like in some parsing libs), use it
    try:
        return value.to_iso_string()
    except Exception:
        pass

    # Final fallback: use the string representation
    try:
        return str(value)
    except Exception as exc:
        raise ValueError(f"unable to dehydrate time value {value!r}") from exc<|return|>

def dehydrate_point(value):
    """Dehydrator for Point data.

    :param value: a :class:`Point` instance
    :type value: Point
    :return: a serialisable representation of the point
    """
    if not isinstance(value, Point):
        raise TypeError(f"Expected a Point instance, got {type(value).__name__}")

    # Prefer an iterable representation if the Point supports iteration
    try:
        return list(value)
    except TypeError:
        pass

    # Fall back to explicit attribute extraction
    data = {}
    for attr in ("x", "y", "z", "latitude", "longitude", "height"):
        if hasattr(value, attr):
            data[attr] = getattr(value, attr)

    if not data:
        raise ValueError(f"The Point instance {value} does not expose coordinate attributes")
    return data<|return|>

def values(self, *keys):
    """
    Return the values of the record, optionally filtering to
    include only certain values by index or key.

    :param keys: indexes or keys of the items to include; if none
                 are provided, all values will be included
    :return: list of values
    :rtype: list
    """
    # Attempt to obtain a full list of values from the record.
    # Prefer a dict‑like representation if available, otherwise fall back to
    # the object's __dict__ (its attributes).
    try:
        full_values = list(self.values())  # may raise recursion if self is this method
    except Exception:
        try:
            full_values = list(vars(self).values())
        except Exception:
            full_values = []

    if not keys:
        return full_values

    result = []
    int_values = None
    for key in keys:
        if isinstance(key, int):
            if int_values is None:
                int_values = full_values
            if -len(int_values) <= key < len(int_values):
                result.append(int_values[key])
        else:
            try:
                result.append(self[key])
            except Exception:
                try:
                    result.append(vars(self).get(key))
                except Exception:
                    pass  # ignore missing keys
    return result<|return|>

def data(self, *keys):
    """ Return the keys and values of this record as a dictionary,
    optionally including only certain values by index or key. Keys
    provided in the items that are not in the record will be
    inserted with a value of :const:`None`; indexes provided
    that are out of bounds will trigger an :exc:`IndexError`.

    :param keys: indexes or keys of the items to include; if none
                  are provided, all values will be included
    :return: dictionary of values, keyed by field name
    :raises: :exc:`IndexError` if an out-of-bounds index is specified
    """
    # Determine the list of field names; expect a `keys` attribute that
    # returns an ordered iterable (e.g., list). If it does not exist,
    # fall back to an empty list to avoid unexpected failures.
    field_names = getattr(self, 'keys', [])
    if not isinstance(field_names, (list, tuple)):
        # If keys is not a sequence, treat it as empty (no known fields)
        field_names = []

    # If no specific keys were supplied, include all fields.
    if not keys:
        result = {}
        for name in field_names:
            result[name] = getattr(self, name, None)
        return result

    result = {}
    for k in keys:
        # Resolve numeric indices into field names.
        if isinstance(k, int):
            if k < 0 or k >= len(field_names):
                raise IndexError(
                    f"Index {k} out of bounds for record with {len(field_names)} fields"
                )
            name = field_names[k]
        elif isinstance(k, str):
            name = k
        else:
            raise TypeError(
                f"Keys must be integers or strings, got {type(k).__name__}"
            )

        # Insert the value or None if the attribute is missing.
        if hasattr(self, name):
            result[name] = getattr(self, name)
        else:
            result[name] = None

    return result<|return|>

def pop_u16(self):
        """Remove the last two bytes of data, returning them as a big-endian
        16‑bit unsigned integer.
        """
        # Ensure the instance has a data attribute
        if not hasattr(self, 'data'):
            raise AttributeError("Instance missing 'data' attribute")
        data = self.data

        # Validate that we have enough data
        try:
            if len(data) < 2:
                raise ValueError("Not enough bytes to pop a 16‑bit integer")
        except TypeError:
            raise TypeError("'data' must support len() and slicing")

        # Extract the last two bytes
        low_bytes = data[-2:]

        # Convert to integer
        try:
            value = int.from_bytes(low_bytes, byteorder='big', signed=False)
        except Exception as exc:
            raise ValueError(f"Failed to convert bytes to int: {exc}")

        # Remove the last two bytes from the data buffer
        if isinstance(data, bytearray):
            # mutable buffer, delete in place
            del data[-2:]
            self.data = data
        else:
            # immutable buffer, create a new slice
            self.data = data[:-2]

        return value<|return|>

def begin(self, mode=None, bookmarks=None, metadata=None, timeout=None,
          db=None, imp_user=None, dehydration_hooks=None,
          hydration_hooks=None, **handlers):
    """
    Appends a BEGIN message to the output queue.

    :param mode: access mode for routing - "READ" or "WRITE" (default)
    :param bookmarks: iterable of bookmark values after which this transaction should begin
    :param metadata: custom metadata dictionary to attach to the transaction
    :param timeout: timeout for transaction execution (seconds)
    :param db: name of the database against which to begin the transaction
        Requires Bolt 4.0+.
    :param imp_user: the user to impersonate
        Requires Bolt 4.4+
    :param dehydration_hooks:
        Hooks to dehydrate types (dict from type (class) to dehydration
        function). Dehydration functions receive the value and returns an
        object of type understood by packstream.
    :param hydration_hooks:
        Hooks to hydrate types (mapping from type (class) to
        dehydration function). Dehydration functions receive the value of
        type understood by packstream and are free to return anything.
    :param handlers: handler functions passed into the returned Response object
    :return: Response object
    """
    # Normalise and validate 'mode'
    if mode is None or mode == "":
        mode = "WRITE"
    elif not isinstance(mode, str):
        raise TypeError(f"mode must be a string, got {type(mode).__name__}")
    mode = mode.upper()
    if mode not in ("READ", "WRITE"):
        raise ValueError("mode must be 'READ' or 'WRITE'")

    # Handle bookmarks
    if bookmarks is not None:
        try:
            bookmarks = list(bookmarks)
        except TypeError:
            raise TypeError("bookmarks must be an iterable of bookmark values")

    # Validate timeout
    if timeout is not None:
        if not isinstance(timeout, (int, float)):
            raise TypeError("timeout must be numeric")
        timeout = float(timeout)

    # Initial message payload
    payload = {
        "mode": mode,
    }
    if bookmarks:
        payload["bookmarks"] = bookmarks
    if metadata:
        payload["metadata"] = metadata
    if timeout is not None:
        payload["timeout"] = timeout
    if db:
        payload["db"] = db
    if imp_user:
        payload["imp_user"] = imp_user

    # Ensure hooks are dictionaries
    dehydration_hooks = dehydration_hooks or {}
    if not isinstance(dehydration_hooks, dict):
        raise TypeError("dehydration_hooks must be a dict mapping type to callable")
    hydration_hooks = hydration_hooks or {}
    if not isinstance(hydration_hooks, dict):
        raise TypeError("hydration_hooks must be a dict mapping type to callable")

    # Validate handlers
    for name, handler in handlers.items():
        if not callable(handler):
            raise TypeError(f"Handler for {name} must be callable")

    # Delegate actual message creation and sending to internal method
    # The internals of the driver are not part of this snippet, so we assume
    # a private method `_begin_transaction` performs the necessary
    # pack-stream encoding and enqueuing logic.
    return self._begin_transaction(
        payload,
        dehydration_hooks=dehydration_hooks,
        hydration_hooks=hydration_hooks,
        **handlers
    )<|return|>

