def cached(cache, key=hashkey, lock=None):
    """Decorator to wrap a function with a memoizing callable that saves
    results in a cache.

    Parameters:
        cache (dict-like): A mapping used to store cached results.
        key (callable): Function used to compute a cache key from the
            function's arguments. Defaults to ``hashkey``.
        lock (context manager or object with ``acquire``/``release``): Optional
            lock used for thread‑safety.

    The cached decorator checks if a result for the computed key already
    exists in *cache*.  If it does, it returns that result.  Otherwise it
    calls the wrapped function, stores its result in the cache, and then
    returns the result.
    """
    if not hasattr(cache, "__getitem__") or not hasattr(cache, "__setitem__"):
        raise TypeError("cache must support dictionary operations")

    if key is None or not callable(key):
        raise TypeError("key must be a callable that returns a hashable key")

    # Ensure the lock behaves like a context manager if provided
    if lock is not None:
        if not hasattr(lock, "acquire") or not hasattr(lock, "release"):
            raise TypeError("lock must provide acquire() and release()")

    def decorator(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            try:
                k = key(*args, **kwargs)
            except Exception:
                # If key computation fails we fallback to direct call
                return func(*args, **kwargs)

            if lock:
                lock.acquire()
            try:
                if k in cache:
                    return cache[k]
                result = func(*args, **kwargs)
                try:
                    cache[k] = result
                except Exception:
                    # Ignore caching failures to not impact function result
                    pass
                return result
            finally:
                if lock:
                    lock.release()
        return wrapper

    return decorator<|return|>

def mru_cache(maxsize=128, typed=False):
    """Decorator to wrap a function with a memoizing callable that saves
    up to `maxsize` results based on a Most Recently Used (MRU)
    algorithm.
    """
    def decorator(func):
        if maxsize <= 0:
            def wrapper(*args, **kwargs):
                return func(*args, **kwargs)
            wrapper.__name__ = func.__name__
            wrapper.__doc__ = func.__doc__
            return wrapper

        cache = {}
        order = []

        def _make_key(args, kwargs, typed_flag):
            if kwargs:
                key = args + tuple(sorted(kwargs.items()))
            else:
                key = args
            if typed_flag:
                key = key + tuple(type(v) for v in args) + tuple(type(v) for v in kwargs.values())
            return key

        def wrapper(*args, **kwargs):
            key = _make_key(args, kwargs, typed)
            if key in cache:
                # Update recency
                order.remove(key)
                order.append(key)
                return cache[key]
            result = func(*args, **kwargs)
            cache[key] = result
            order.append(key)
            if len(order) > maxsize:
                # Evict MRU entry
                evict_key = order.pop()
                del cache[evict_key]
            return result

        wrapper.__name__ = func.__name__
        wrapper.__doc__ = func.__doc__
        return wrapper

    return decorator<|return|>

