def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    # Validate iterable and convert to list
    try:
        orig = list(classes)
    except TypeError:
        raise TypeError("Expected an iterable of types")

    # Ensure every element is a class type
    for cls in orig:
        if not isinstance(cls, type):
            raise TypeError(f"Expected a class, got {type(cls)!r}")

    # Determine which classes are not superclasses of any other in the list
    keep_set = set()
    for cls in orig:
        # cls is kept only if no other class in the list is a subclass of cls
        if not any(issubclass(other, cls) and other is not cls for other in orig):
            keep_set.add(cls)

    # Preserve original order and remove duplicates
    result = []
    seen = set()
    for cls in orig:
        if cls in keep_set and cls not in seen:
            result.append(cls)
            seen.add(cls)

    return result<|return|>

def _normalizeargs(sequence, output=None):
    """Normalize declaration arguments

    Normalization arguments might contain Declarions, tuples, or single
    interfaces.

    Anything but individial interfaces or implements specs will be expanded.
    """
    if output is None:
        output = []

    for item in sequence:
        # Treat strings and bytes as atomic items, everything else is expanded
        if isinstance(item, (list, tuple)):
            output.extend(item)
        else:
            output.append(item)

    return output<|return|>

