def integral(bins, edges):
    """Compute integral (scale for a histogram).

    *bins* contain values, and *edges* form the mesh
    for the integration.
    Their format is defined in :class:`.histogram` description.
    """
    # Basic argument validation
    try:
        len_b = len(bins)
        len_e = len(edges)
    except Exception as exc:
        raise TypeError("bins and edges must be sequences") from exc

    if len_e != len_b + 1:
        raise ValueError("edges length must be one greater than bins length")

    if len_b == 0:
        return 0.0

    # Ensure edges are monotonically increasing
    for i in range(len_e - 1):
        if edges[i + 1] <= edges[i]:
            raise ValueError("edges must be strictly increasing")

    total = 0.0
    for i in range(len_b):
        width = edges[i + 1] - edges[i]
        total += bins[i] * width

    return float(total)<|return|>

