def difference(d1, d2, level=-1):
    """Return a dictionary with items from *d1* not contained in *d2*.

    *level* sets the maximum depth of recursion. For infinite recursion,
    set that to -1. For level 1,
    if a key is present both in *d1* and *d2* but has different values,
    it is included into the difference.
    See :func:`intersection` for more details.

    *d1* and *d2* remain unchanged. However, *d1* or some of its
    subdictionaries may be returned directly.
    Make a deep copy of the result when appropriate.

    .. versionadded:: 0.5
       add keyword argument *level*.
    """
    def _diff(sub1, sub2, current_level):
        result = {}
        for key, val in sub1.items():
            if key not in sub2:
                # include the whole subdictionary or value directly
                result[key] = val
            else:
                val2 = sub2[key]
                # If both are dicts, recurse respecting level
                if isinstance(val, dict) and isinstance(val2, dict):
                    if current_level == 0:
                        # Do not recurse further; treat as a difference
                        result[key] = val
                    else:
                        next_level = current_level - 1 if current_level > 0 else -1
                        diff_sub = _diff(val, val2, next_level)
                        if diff_sub:
                            result[key] = diff_sub
                elif val != val2:
                    result[key] = val
        return result

    return _diff(d1, d2, level)<|return|>

def fill(self, coord, weight=1):
    """Fill histogram at *coord* with the given *weight*.

    Coordinates outside the histogram edges are ignored.
    """
    # Ensure weight is a number
    try:
        weight = float(weight)
    except Exception as exc:
        raise TypeError(f"weight must be numeric, got {weight!r}") from exc

    # Convert coordinate to an array for easier indexing
    try:
        coord_arr = np.asarray(coord, dtype=float)
    except Exception as exc:
        raise TypeError(f"coord must be array-like, got {coord!r}") from exc

    # Handle scalar coordinates
    if coord_arr.ndim == 0:
        coord_arr = coord_arr.reshape(1)

    # Expect one coordinate per dimension of the histogram
    if coord_arr.size != len(self.edges):
        raise ValueError(
            f"coord must have {len(self.edges)} dimensions, got {coord_arr.size}"
        )

    # Determine the bin indices for each dimension
    bin_idx = []
    for dim, (edge, val) in enumerate(zip(self.edges, coord_arr)):
        # Use np.searchsorted to find the bin index
        # `right=False` ensures values equal to an edge fall into the left bin
        try:
            idx = np.searchsorted(edge, val, side='right') - 1
        except Exception as exc:
            raise ValueError(f"Error determining bin for value {val} in dimension {dim}") from exc

        # If coordinate is outside histogram range, ignore
        if idx < 0 or idx >= len(edge) - 1:
            return  # silently ignore out-of-range coordinates

        bin_idx.append(idx)

    # Increment the histogram bin
    try:
        self.bins[tuple(bin_idx)] += weight
    except Exception as exc:
        # In case the bins array is not found or indexing fails
        raise RuntimeError(f"Failed to increment histogram bin {tuple(bin_idx)}") from exc
    return None<|return|>

def _validate_labels(labels):
