            try:
                if not re.match(_LABEL_KEY_REGEX, key):
                    errors.append({key: f"Label key '{key}' does not match the regex {_LABEL_KEY_REGEX}"})
            except Exception:
                errors.append({key: f"Invalid regular expression {_LABEL_KEY_REGEX}"})

        # Validate value(s)
        if isinstance(value, (list, tuple)):
            for val in value:
                if not isinstance(val, (str, bytes)):
                    errors.append({str(val): 'expected string or bytes-like object'})
                else:
                    try:
                        if not re.match(_LABEL_VALUE_REGEX, val):
                            errors.append({val: f"Label value '{val}' does not match the regex {_LABEL_VALUE_REGEX}"})
                    except Exception:
                        errors.append({val: f"Invalid regular expression {_LABEL_VALUE_REGEX}"})
        else:
            if not isinstance(value, (str, bytes)):
                errors.append({str(value): 'expected string or bytes-like object'})
            else:
                try:
                    if not re.match(_LABEL_VALUE_REGEX, value):
                        errors.append({value: f"Label value '{value}' does not match the regex {_LABEL_VALUE_REGEX}"})
                except Exception:
                    errors.append({value: f"Invalid regular expression {_LABEL_VALUE_REGEX}"})

    if errors:
        raise ValidationError(errors)<|return|>

def validate_key(key):
    """Validate the given key against the corresponding regular expression.

    Args:
        key: the string to validate

    Raises:
        ValidationError: if the given key is not conform to the regular expression.
    """
    if not isinstance(key, str):
        raise ValidationError('Key must be a string')
    try:
        if not re.fullmatch(KEY_REGEX, key):
            raise ValidationError(f'Invalid key: {key!r}')
    except Exception as exc:
        raise ValidationError(f'Error validating key: {exc}') from exc<|return|>

def update_last_applied_manifest_dict_from_resp(
    last_applied_manifest, observer_schema, response
):
    """Together with :func:``update_last_applied_manifest_list_from_resp``, this
    function is called recursively to update a partial ``last_applied_manifest``
    from a partial Kubernetes response

    Args:
        last_applied_manifest (dict): partial ``last_applied_manifest`` being
            updated
        observer_schema (dict): partial ``observer_schema``
        response (dict): partial response from the Kubernetes API.

    Raises:
        KeyError: If the observed field is not present in the Kubernetes response

    This function go through all observed fields, and initialized their value in
    last_applied_manifest if they are not yet present

    """
    for key, sub_schema in observer_schema.items():
        if key not in response:
            raise KeyError(f"Field {key!r} not found in response")
        value = response[key]

        # Leaf scalar that should be copied if not already present
        if sub_schema is True:
            if key not in last_applied_manifest:
                last_applied_manifest[key] = value
            continue

        # If sub_schema is a dict, it describes nested structure
        if not isinstance(sub_schema, dict):
            raise TypeError(
                f"Observer schema for {key!r} must be True or dict, got {type(sub_schema).__name__}"
            )

        # Ensure the nested dict exists in the manifest
        if key not in last_applied_manifest or not isinstance(last_applied_manifest[key], dict):
            last_applied_manifest[key] = {}

        if not isinstance(value, dict):
            raise KeyError(
                f"Expected a dict for field {key!r} in response, got {type(value).__name__}"
            )

        # Recurse into nested structure
        update_last_applied_manifest_dict_from_resp(
            last_applied_manifest[key], sub_schema, value
        )<|return|>

def generate_default_observer_schema(app):
    """Generate the default observer schema for each Kubernetes resource present in
    ``spec.manifest`` for which a custom observer schema hasn't been specified.

    Args:
        app (krake.data.kubernetes.Application): The application for which to generate a
            default observer schema
    """
    # Validate the input
    if app is None:
        raise ValueError("app must not be None")
    # Ensure the spec and manifest exist
    try:
        manifest = app.spec.manifest
    except AttributeError:
        raise AttributeError("Application object does not have a 'spec' or 'spec.manifest' attribute")

    # Ensure container for observer schemas
    if not hasattr(app, "observer_schema") or app.observer_schema is None:
        app.observer_schema = {}

    # Collect resources from the manifest (list or dict)
    resources = []
    if isinstance(manifest, list):
        resources = manifest
    elif isinstance(manifest, dict):
        # The manifest may be a mapping of resource names to resource objects
        resources = list(manifest.values())
    else:
        raise TypeError("app.spec.manifest must be a list or dict of resources")

    for res in resources:
        # Skip if we cannot determine the kind
        kind = getattr(res, "kind", None)
        if kind is None:
            # If a dict, try the key
            kind = res.get("kind") if isinstance(res, dict) else None
        if not kind:
            continue

        # Determine the resource name (if any)
        name = None
        metadata = getattr(res, "metadata", None)
        if metadata is None and isinstance(res, dict):
            metadata = res.get("metadata", {})
        if isinstance(metadata, dict):
            name = metadata.get("name")

        # Use a tuple key (kind, name) for the schema recording
        key = (kind, name)

        # If a custom schema exists, skip creating a default one
        if key in app.observer_schema:
            continue

        # Build a minimal default schema
        default_schema = {
            "kind": kind,
            "name": name,
            "apiVersion": getattr(res, "apiVersion", None)
        }
        if default_schema["apiVersion"] is None and isinstance(res, dict):
            default_schema["apiVersion"] = res.get("apiVersion")

        # Store the default schema
        app.observer_schema[key] = default_schema

    # Return None to indicate that the operation has been performed
    return None<|return|>

def status_str(self, prefix=''):
    """Return string of validator status, with optional prefix."""
    try:
        status = getattr(self, 'status', None)
        if status is None:
            return prefix
        if isinstance(status, dict):
            status_str = ', '.join(f'{k}={v}' for k, v in status.items())
        else:
            status_str = str(status)
        return prefix + status_str
    except Exception as exc:
        return prefix + f'Error getting status: {exc}'<|return|>

def status_str(self, prefix=''):
    """Return string representation of validation log, with optional prefix."""
    if not isinstance(prefix, str):
        raise TypeError("prefix must be a string")

    # Try to find a validation log attribute
    log = getattr(self, 'validation_log', None)
    if log is None:
        log = getattr(self, '_validation_log', None)

    if log is None:
        return ''

    try:
        iterator = iter(log)
    except TypeError:
        # log is not iterable; treat as a single entry
        return prefix + str(log)

    lines = []
    for entry in log:
        try:
            lines.append(prefix + str(entry))
        except Exception:
            lines.append(prefix + repr(entry))
    return '\n'.join(lines)<|return|>

def check_digests_present_and_used(self, manifest_files, digests_used):
    """Check all digests in manifest that are needed are present and used."""
    # Validate inputs
    if manifest_files is None:
        raise TypeError("manifest_files must be provided and non‑None")
    if digests_used is None:
        raise TypeError("digests_used must be provided and non‑None")

    # Build a set of the digests that appear in the manifest
    try:
        manifest_set = set()
        for f in manifest_files:
            # Accept either a dict with a 'digest' key or an object with a 'digest' attribute
            if isinstance(f, dict):
                digest = f.get("digest")
            else:
                digest = getattr(f, "digest", None)
            if digest is None:
                raise ValueError(f"Manifest entry {f!r} does not contain a valid digest")
            manifest_set.add(digest)
    except Exception as exc:
        raise ValueError(f"Error while processing manifest files: {exc}") from exc

    # Build the set of digests that are required
    try:
        needed_set = set(digests_used)
    except TypeError as exc:
        raise TypeError("digests_used must be an iterable of digests") from exc

    # Digests that are required but missing from the manifest
    missing = needed_set - manifest_set
    if missing:
        missing_list = ", ".join(sorted(missing))
        raise ValueError(
            f"The following required digests are missing from the manifest: {missing_list}"
        )

    # Optionally warn about digests present in the manifest but not used
    unused = manifest_set - needed_set
    if unused:
        # In many contexts simply ignoring unused digests is fine; you could
        # log a warning or raise a warning exception if desired.
        pass

    # No return value needed; success is indicated by the absence of an exception.<|return|>

def get_logical_path_map(inventory, version):
    """Get a map of logical paths in state to files on disk for version in inventory.

    Returns a dictionary: logical_path_in_state -> set(content_files)

    The set of content_files may includes references to duplicate files in
    later versions than the version being described.
    """
    # helper to provide a sortable key for versions
    def _sortable(v):
        try:
            return float(v)
        except Exception:
            return str(v)

    # Ensure inventory is a mapping
    if not isinstance(inventory, dict):
        raise TypeError("inventory must be a mapping of version -> (logical_path -> content_file)")

    # Validate the requested version exists
    if version not in inventory:
        # Version not present: return empty mapping
        return {}

    # Base mapping from logical path to set of content files
    logical_to_files = {}

    try:
        base_map = inventory[version]
        if not isinstance(base_map, dict):
            raise TypeError(f"inventory[{version!r}] must be a mapping of logical_path -> content_file")
        for lp, cf in base_map.items():
            logical_to_files.setdefault(lp, set()).add(cf)
    except Exception as exc:
        raise ValueError(f"Error processing inventory[{version!r}]: {exc}") from exc

    # include duplicates from later versions
    try:
        for other_version in inventory:
            if other_version == version:
                continue
            # consider "later" versions
            try:
                if _sortable(other_version) > _sortable(version):
                    other_map = inventory[other_version]
                    if not isinstance(other_map, dict):
                        continue
                    for lp, cf in other_map.items():
                        if lp in logical_to_files:
                            logical_to_files[lp].add(cf)
            except Exception:
                continue
    except Exception as exc:
        raise RuntimeError(f"Error while collecting later versions: {exc}") from exc

    return logical_to_files<|return|>

def files_list(path):
    """Return the files in ``path``."""
    if not isinstance(path, (str, bytes)):
        raise TypeError(f"path must be a string or bytes, got {type(path).__name__}")

    try:
        if not os.path.exists(path):
            raise FileNotFoundError(f"The path does not exist: {path}")
        if not os.path.isdir(path):
            raise NotADirectoryError(f"The path is not a directory: {path}")
    except AttributeError as exc:
        # os module not available; propagate original error
        raise

    try:
        entries = os.listdir(path)
    except OSError as exc:
        raise OSError(f"Could not list directory '{path}': {exc}") from exc

    files = []
    for name in entries:
        full_path = os.path.join(path, name)
        try:
            if os.path.isfile(full_path):
                files.append(name)
        except OSError:
            # skip entries we can't stat
            continue

    return sorted(files)<|return|>

def match_pubdate(node, pubdate_xpaths):
    """Retorna o primeiro match da lista de pubdate_xpaths"""
    if node is None or not pubdate_xpaths:
        return None

    for xpath in pubdate_xpaths:
        try:
            matches = node.xpath(xpath)
        except Exception:
            # If the xpath is invalid or execution fails, skip to the next one
            continue

        if matches:
            return matches[0]

    return None<|return|>

def pretty(self, indent=0, debug=False):
        """Return a pretty formatted representation of self."""
        try:
            def _format(obj, level):
                space = ' ' * level
                lines = [f"{space}{obj.__class__.__name__}"]
                if hasattr(obj, "__dict__"):
                    for key, val in sorted(obj.__dict__.items()):
                        if isinstance(val, (list, tuple)):
                            for item in val:
                                if hasattr(item, "pretty"):
                                    lines.append(_format(item, level + 4))
                                else:
                                    lines.append(f"{space}{' ' * 4}{key}: {item!r}")
                        elif hasattr(val, "pretty"):
                            lines.append(_format(val, level + 4))
                        elif key in ("cls", "id", "text"):
                            # Common attributes
                            lines.append(f"{space}{' ' * 4}{key}: {val!r}")
                        else:
                            lines.append(f"{space}{' ' * 4}{key}: {val!r}")
                if debug and hasattr(obj, "id"):
                    lines.append(f"{space}{' ' * 4}debug id={getattr(obj, 'id')!r}")
                return "\n".join(lines)

            return _format(self, indent)
        except Exception as exc:
            return f"<pretty error: {exc}>"
<|return|>

def on(self, hook):
        """Decorator function to add a new handler to the registry.

        Args:
            hook (HookType): Hook attribute for which to register the handler.

        Returns:
            callable: Decorator for registering listeners for the specified hook.

        """
        # Sanity check the hook value (allow any hashable object if HookType is not available)
        try:
            is_instance = isinstance
        except Exception:
            is_instance = lambda obj, typ: True  # fallback that always passes

        # If HookType is defined somewhere, we prefer to check against it.
        try:
            HookType
        except NameError:
            HookType = type(None)  # dummy type when not defined

        if not is_instance(hook, HookType):
            raise TypeError(
                f"hook must be an instance of HookType, got {type(hook).__name__}"
            )

        def decorator(func):
            if not callable(func):
                raise TypeError("The handler must be a callable")

            # Ensure a registry dict exists on the instance
            if not hasattr(self, "_handler_registry") or not isinstance(
                self._handler_registry, dict
            ):
                self._handler_registry = {}

            # Retrieve the list for this hook, creating it if necessary
            handlers = self._handler_registry.setdefault(hook, [])

            # Avoid duplicate registration
            if func in handlers:
                return func

            handlers.append(func)
            return func

        return decorator<|return|>

def tzname_in_python2(namefunc):
    """Change unicode output into bytestrings in Python 2

    tzname() API changed in Python 3. It used to return bytes, but was changed
    to unicode strings
    """
    import sys
    if sys.version_info[0] < 3:
        # Python 2: ensure the returned value is a byte string
        def _wrapper(*args, **kwargs):
            try:
                result = namefunc(*args, **kwargs)
            except Exception as exc:
                # If the wrapped function itself raises an exception,
                # we propagate it unchanged.
                raise
            # In Python 2 the type 'unicode' exists; use it if available.
            try:
                unicode_type = unicode  # noqa: F821
            except NameError:
                unicode_type = str  # type fallback, but should never happen in Py2
            if isinstance(result, unicode_type):
                try:
                    return result.encode('utf-8')
                except UnicodeEncodeError:
                    # Fallback to filesystem encoding with replacement
                    return result.encode(sys.getfilesystemencoding(), 'replace')
            return result
        return _wrapper
    # Python 3: leave the function unchanged
    return namefunc<|return|>

def get_versions():
    """Get version information or return default if unable to do so."""
    # Try to import importlib.metadata (Python 3.8+). Fall back to importlib_metadata for older versions.
    try:
        import importlib.metadata as importlib_metadata
    except ImportError:
        try:
            import importlib_metadata  # e.g. backport
            importlib_metadata = importlib_metadata
        except Exception:
            # No importlib.metadata available
            return "unknown"

    # Determine a suitable distribution name.
    # Prefer __package__ (module package), otherwise __name__.
    pkg_name = __package__ or __name__
    # Strip any script niceties (.__main__ etc.).
    if pkg_name.endswith(".__main__"):
        pkg_name = pkg_name.rsplit(".", 2)[0]

    # Normal lookup via version().
    try:
        version = importlib_metadata.version(pkg_name)
        return version
    except Exception:
        # Possibly the distribution is installed but named differently.
        # Attempt to fetch via distribution() which may provide a more robust lookup.
        try:
            from importlib.metadata import distribution  # Python 3.10+
            version = distribution(pkg_name).version
            return version
        except Exception:
            # All lookups failed; fallback to a generic string.
            return "unknown"<|return|>

def render(pieces, style):
    """Render the given version pieces into the requested style."""
    # Validate inputs
    if not isinstance(pieces, (list, tuple)):
        raise TypeError("pieces must be a list or tuple of strings")
    if not isinstance(style, str):
        raise TypeError("style must be a string")
    # Normalize style
    style = style.lower()
    # Define supported styles
    if style in ("plain", "text", "txt"):
        # Join pieces with comma and space
        try:
            return ", ".join(str(p) for p in pieces)
        except Exception as e:
            raise RuntimeError(f"Error rendering plain style: {e}") from e
    elif style == "json":
        try:
            import json
            return json.dumps(pieces)
        except Exception as e:
            raise RuntimeError(f"Error rendering json style: {e}") from e
    elif style == "xml":
        try:
            # Simple XML representation
            lines = ["<pieces>"]
            for p in pieces:
                lines.append(f"  <item>{p}</item>")
            lines.append("</pieces>")
            return "\n".join(lines)
        except Exception as e:
            raise RuntimeError(f"Error rendering xml style: {e}") from e
    else:
        raise ValueError(f"Unsupported style '{style}'. Supported styles: plain, json, xml.")<|return|>

def plus_or_dot(pieces):
    """Return a + if we don't already have one, else return a ."""
    try:
        # Ensure pieces is iterable; treat None or non-iterables as empty
        if pieces is None:
            return '+'
        for p in pieces:
            if p == '+':
                return '.'
        return '+'
    except TypeError as e:
        raise ValueError("pieces must be an iterable of elements") from e<|return|>

def run_command(commands, args, cwd=None, verbose=False, hide_stderr=False, env=None):
    """Call the given command(s)."""
    import subprocess, os, shlex

    # Validate and build the command list
    if isinstance(commands, str):
        base_cmd = shlex.split(commands)
    elif isinstance(commands, list):
        base_cmd = list(commands)
    else:
        raise TypeError("commands must be a string or a list of strings")
    if isinstance(args, str):
        args_list = shlex.split(args)
    elif isinstance(args, list):
        args_list = list(args)
    elif args is None:
        args_list = []
    else:
        raise TypeError("args must be a string, a list of strings, or None")
    full_cmd = base_cmd + args_list

    if verbose:
        print(f"Running command: {' '.join(full_cmd)}")
        if cwd:
            print(f"  working directory: {cwd}")

    # Merge environment variables if provided
    env_dict = os.environ.copy()
    if env:
        env_dict.update(env)

    # Handle stderr according to hide_stderr
    stderr_setting = subprocess.DEVNULL if hide_stderr else subprocess.PIPE

    try:
        result = subprocess.run(
            full_cmd,
            cwd=cwd,
            stdout=subprocess.PIPE,
            stderr=stderr_setting,
            env=env_dict,
            text=True,
            check=False  # do not raise on non-zero exit code
        )
    except FileNotFoundError as e:
        raise RuntimeError(f"Command not found: {full_cmd[0]}") from e
    except Exception as e:
        raise RuntimeError(f"Error running command: {' '.join(full_cmd)}") from e

    # Optionally print stderr when not hidden
    if not hide_stderr and verbose and result.stderr:
        print(result.stderr, end='')

    # Return a tuple of (returncode, stdout, stderr)
    return result.returncode, result.stdout, result.stderr

<|return|>

def register_vcs_handler(vcs, method=None):
    """Create decorator to mark a method as the handler of a VCS."""
    if not isinstance(vcs, str) or not vcs:
        raise ValueError("vcs must be a non-empty string")
    def decorator(func):
        if not callable(func):
            raise TypeError("Provided method must be callable")
        setattr(func, "_vcs_handler", vcs)
        return func
    if method is None:
        return decorator
    return decorator(method)<|return|>

def validate_hierarchy(self, validate_objects=True, check_digests=True, show_warnings=False):
    """Validate storage root hierarchy.

    Returns:
        num_objects - number of objects checked
        good_objects - number of objects checked that were found to be valid
    """
    num_objects = 0
    good_objects = 0

    # Iterate over all elements in this hierarchy including self
    try:
        iterator = iter(self)
    except TypeError:
        # If self is not iterable, treat it as a single element
        iterator = [self]

    for element in iterator:
        num_objects += 1
        is_valid = True

        # Validate the object itself if requested and if a validate method exists
        if validate_objects and hasattr(element, "validate"):
            try:
                element.validate()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Validation warning for {getattr(element, 'id', 'unknown')} ({type(element).__name__}): {exc}")

        # Check the digest if requested and if a check_digest method exists
        if check_digests and hasattr(element, "check_digest"):
            try:
                element.check_digest()
            except Exception as exc:
                is_valid = False
                if show_warnings:
                    print(f"Digest warning for {getattr(element, 'id', 'unknown')} ({type(element).__name__}): {exc}")

        if is_valid:
            good_objects += 1

    return num_objects, good_objects<|return|>

def initialize(self):
    """Create and initialize a new OCFL storage root."""
    import os
    # Determine the root directory from the object's attribute.
    root_path = getattr(self, 'path', None) or getattr(self, 'root', None)

    if not root_path:
        raise AttributeError("The object does not define a 'path' or 'root' attribute for the storage root.")

    # Ensure the root directory exists and is empty
    try:
        if os.path.exists(root_path):
            if not os.path.isdir(root_path):
                raise OSError(f"'{root_path}' exists but is not a directory.")
            # Ensure the directory is empty – an initialized OCFL root must not contain files.
            if os.listdir(root_path):
                raise FileExistsError(f"Cannot initialize OCFL root: '{root_path}' already contains files.")
        else:
            os.makedirs(root_path, exist_ok=True)
    except OSError as exc:
        raise OSError(f"Failed to create or verify storage root at '{root_path}': {exc}") from exc

    # Create the required ocfl_version.txt file.
    try:
        version_file = os.path.join(root_path, "ocfl_version.txt")
        with open(version_file, "w", encoding="utf-8") as f:
            f.write("OCFL/1.0")
    except OSError as exc:
        raise OSError(f"Failed to write ocfl_version.txt in '{root_path}': {exc}") from exc

    # Create the mandatory subdirectories: objects/ and support/
    for subdir in ("objects", "support"):
        try:
            os.makedirs(os.path.join(root_path, subdir), exist_ok=True)
        except OSError as exc:
            raise OSError(f"Failed to create subdirectory '{subdir}' in '{root_path}': {exc}") from exc

    # Initialization succeeded
    return None<|return|>

def validate_version_inventories(self, version_dirs):
        """Each version SHOULD have an inventory up to that point.

        Also keep a record of any content digests different from those in the root inventory
        so that we can also check them when validating the content.

        version_dirs is an array of version directory names and is assumed to be in
        version sequence (1, 2, 3...).
        """
        # Basic validation of input
        if not isinstance(version_dirs, (list, tuple)):
            raise TypeError("version_dirs must be a list or tuple of directory names")
        if any(not isinstance(v, str) for v in version_dirs):
            raise ValueError("All items in version_dirs must be strings")

        # Check we have a method to load an inventory (expected to return a dict of key->digest)
        if not hasattr(self, "get_inventory") or not callable(self.get_inventory):
            raise AttributeError("The object must provide a 'get_inventory' method that returns a dictionary of digests for a given directory")

        # Load the root inventory (assumed to be in a standard place, e.g. self.root_dir/inventory.xml)
        try:
            root_inventory = self.get_inventory(self.root_dir)
        except Exception as exc:
            raise RuntimeError("Failed to load root inventory") from exc

        # Keep track of digests that differ from the root
        differing_digest_map = {}

        # Iterate over the supplied version directories in order
        for idx, vdir in enumerate(version_dirs, start=1):
            # Load the inventory for this particular version directory
            try:
                inv = self.get_inventory(vdir)
            except Exception as exc:
                raise RuntimeError(f"Failed to load inventory for '{vdir}'") from exc

            # Ensure that the inventory for this version contains at least everything in the root inventory
            missing_keys = set(root_inventory.keys()) - set(inv.keys())
            if missing_keys:
                raise ValueError(f"Inventory in version '{vdir}' is missing keys: {sorted(missing_keys)}")

            # Compare digests against the root inventory
            for key, digest in inv.items():
                root_digest = root_inventory.get(key)
                if root_digest is not None and digest != root_digest:
                    differing_digest_map.setdefault(key, []).append((vdir, digest))

        # Store the differences for later validation
        self._differing_digests = differing_digest_map

        # If we reach here, validation of inventory existence succeeded
        return True

<|return|>

def parser_flags(parser):
    """
    Given an argparse.ArgumentParser instance, return its argument flags in a
    space-separated string.
    """
    try:
        flags = []
        for action in getattr(parser, "_actions", []):
            opt_strs = getattr(action, "option_strings", None)
            if opt_strs:
                flags.extend(opt_strs)
        return " ".join(flags)
    except Exception:
        return ""<|return|>

def make_parsers():
    """
    Build a top-level parser and its subparsers and return them as a tuple.
    """
    import argparse

    try:
        parser = argparse.ArgumentParser(description="Main parser")
    except Exception as exc:
        raise RuntimeError(f"Failed to create main parser: {exc}") from exc

    try:
        subparsers = parser.add_subparsers(dest='command', required=True)
    except Exception as exc:
        raise RuntimeError(f"Failed to create subparsers: {exc}") from exc

    # Example subparser definitions – can be extended as needed
    try:
        parser_a = subparsers.add_parser('a', help='Command a')
        parser_a.add_argument('--foo', help='foo parameter')
    except Exception as exc:
        raise RuntimeError(f"Failed to configure subparser 'a': {exc}") from exc

    try:
        parser_b = subparsers.add_parser('b', help='Command b')
        parser_b.add_argument('--bar', type=int, help='bar parameter')
    except Exception as exc:
        raise RuntimeError(f"Failed to configure subparser 'b': {exc}") from exc

    return parser, subparsers<|return|>

def parser_flags(parser):
    """Given an argparse.ArgumentParser instance, return its argument flags in a space‑separated string."""
    # Validate the input
    if parser is None:
        raise TypeError("parser must not be None")
    if not hasattr(parser, "_actions"):
        raise TypeError("Expected an argparse.ArgumentParser instance, got %r" % type(parser).__name__)
    # Collect all option strings from the parser's actions
    flags = []
    for action in parser._actions:
        # action.option_strings is a list of the flag names for that action
        if hasattr(action, "option_strings"):
            flags.extend(action.option_strings)
    return " ".join(flags)<|return|>

def paging(response, max_results):
    """Returns WAPI response page by page

    Args:
        response (list): WAPI response.
        max_results (int): Maximum number of objects to be returned in one page.
    Returns:
        Generator object with WAPI response split page by page.
    """

    # Validate inputs
    if not isinstance(response, list):
        raise TypeError("response must be a list")
    if not isinstance(max_results, int):
        raise TypeError("max_results must be an integer")
    if max_results <= 0:
        raise ValueError("max_results must be a positive integer")

    # Return generator that yields slices of the list
    try:
        return (response[i:i + max_results] for i in range(0, len(response), max_results))
    except Exception as e:
        raise RuntimeError(f"An error occurred while splitting the response into pages: {e}") from e<|return|>

def _dictsum(dicts):
    """
    Combine values of the dictionaries supplied by iterable dicts.

    >>> _dictsum([{'a': 1, 'b': 2}, {'a': 5, 'b': 0}])
    {'a': 6, 'b': 2}
    """
    if dicts is None:
        return {}
    try:
        iterator = iter(dicts)
    except TypeError:
        raise TypeError(f"_dictsum expects an iterable of dicts, got {type(dicts).__name__}")
    result = {}
    for d in iterator:
        if not isinstance(d, dict):
            raise TypeError(f"Expected each item to be a dict, got {type(d).__name__}")
        for k, v in d.items():
            if not isinstance(v, (int, float)):
                raise ValueError(f"Dictionary values must be numeric to sum; got {type(v).__name__} for key {k!r}")
            result[k] = result.get(k, 0) + v
    return result<|return|>

def is_none_string(val: any) -> bool:
    """Check if a string represents a None value."""
    try:
        s = str(val).strip()
    except Exception:
        # If conversion to string fails, treat it as not a None string
        return False

    # Empty strings are not considered a None representation
    if not s:
        return False

    # Define common string representations of None or missing values
    none_values = {'none', 'null', 'n/a', 'na', '-'}
    return s.lower() in none_values<|return|>

def int_to_string(number: int, alphabet: List[str], padding: Optional[int] = None) -> str:
    """
    Convert a number to a string, using the given alphabet.

    The output has the most significant digit first.
    """
    if not isinstance(number, int):
        raise TypeError(f"number must be an int, got {type(number).__name__}")
    if number < 0:
        raise ValueError("number must be non-negative")
    if not isinstance(alphabet, list) or len(alphabet) == 0:
        raise ValueError("alphabet must be a non-empty list")
    if padding is not None and not isinstance(padding, int):
        raise TypeError(f"padding must be an int or None, got {type(padding).__name__}")
    if padding is not None and padding < 0:
        raise ValueError("padding must be non-negative")

    base = len(alphabet)
    # Special case: zero
    if number == 0:
        result = alphabet[0]
    else:
        digits = []
        n = number
        while n > 0:
            n, rem = divmod(n, base)
            digits.append(alphabet[rem])
        result = ''.join(reversed(digits))

    if padding is not None and len(result) < padding:
        pad_char = alphabet[0]
        result = pad_char * (padding - len(result)) + result

    return result<|return|>

def _replace_register(flow_params, register_number, register_value):
    """Replace value from flows to given register number

    'register_value' key in dictionary will be replaced by register number
    given by 'register_number'

    :param flow_params: Dictionary containing defined flows
    :param register_number: The number of register where value will be stored
    :param register_value: Key to be replaced by register number

    """
    if not isinstance(flow_params, dict):
        raise TypeError(f"flow_params must be a dict, got {type(flow_params).__name__}")
    if register_value is None:
        raise ValueError("register_value must not be None")
    if register_number is None:
        raise ValueError("register_number must not be None")
    try:
        value = flow_params.pop(register_value)
    except KeyError as exc:
        raise KeyError(f"Key '{register_value}' not found in flow_params") from exc
    flow_params[register_number] = value
    # The operation modifies flow_params in place; no return value is needed.<|return|>

def replace_dots(value, arg):
    """Replaces all values of '.' to arg from the given string"""
    # Ensure the inputs are strings; raise clear errors if not
    if not isinstance(value, str):
        raise TypeError(f"value must be a string, got {type(value).__name__}")
    if not isinstance(arg, str):
        raise TypeError(f"arg must be a string, got {type(arg).__name__}")

    # Perform the replacement
    return value.replace('.', arg)<|return|>

def subclasses(cls):
    """Return all subclasses of a class, recursively"""
    if not isinstance(cls, type):
        raise TypeError(f"Expected a class, got {type(cls).__name__}")
    seen = set()
    stack = list(cls.__subclasses__())
    while stack:
        sub = stack.pop()
        if sub not in seen:
            seen.add(sub)
            stack.extend(sub.__subclasses__())
    return list(seen)<|return|>

def unquote(name):
    """Remove quote from the given name."""
    if not isinstance(name, str):
        raise TypeError(f"name must be a string, got {type(name).__name__}")
    # Remove surrounding single or double quotes if they match
    match = re.fullmatch(r"(?P<quote>['\"])(?P<inner>.*?)(?P=quote)", name)
    if match:
        return match.group("inner")
    return name<|return|>

def match(filename):
    """
    Check if the filename is a type that this module supports

    Args:
        filename: Filename to match
    Returns:
        False if not a match, True if supported
    """
    try:
        if not isinstance(filename, str):
            return False
        _, ext = os.path.splitext(filename)
        return ext.lower() in {'.txt', '.md', '.rst'}
    except Exception:
        return False<|return|>

def parse_frequency(frequency):
    '''
    Given a frequency string with a number and a unit of time, return a corresponding
    datetime.timedelta instance or None if the frequency is None or "always".

    For instance, given "3 weeks", return datetime.timedelta(weeks=3)

    Raise ValueError if the given frequency cannot be parsed.
    '''
    if frequency is None:
        return None
    if isinstance(frequency, str) and frequency.strip().lower() == 'always':
        return None
    if not isinstance(frequency, str):
        raise ValueError(f"Frequency must be a string or None, got {type(frequency).__name__}")
    parts = frequency.strip().lower().split()
    if len(parts) != 2:
        raise ValueError(f"Could not parse frequency: '{frequency}'. Expected '<number> <unit>'")
    number_str, unit = parts
    try:
        number = float(number_str)
    except ValueError:
        raise ValueError(f"Could not parse number in frequency: '{number_str}'")
    kwargs = {}
    if unit in ('week', 'weeks'):
        kwargs['weeks'] = number
    elif unit in ('day', 'days'):
        kwargs['days'] = number
    elif unit in ('hour', 'hours'):
        kwargs['hours'] = number
    elif unit in ('minute', 'minutes'):
        kwargs['minutes'] = number
    elif unit in ('second', 'seconds'):
        kwargs['seconds'] = number
    else:
        raise ValueError(f"Unknown time unit '{unit}' in frequency: '{frequency}'")
    return datetime.timedelta(**kwargs)<|return|>

def is_local(host):
    """Checks if the host is the localhost

    :param host: The hostname or ip
    :return: True if the host is the localhost
    """
    # Basic string checks for common localhost names
    try:
        host_str = host.strip().lower()
        if host_str in ("localhost", "127.0.0.1", "::1", "0.0.0.0"):
            return True
        local_name = socket.gethostname().lower()
        if host_str == local_name:
            return True
    except Exception:
        pass

    # Resolve the host to a set of IPs
    try:
        host_ips = {res[4][0] for res in socket.getaddrinfo(host, None)}
    except socket.gaierror:
        return False
    except Exception:
        return False

    # Gather local machine IPs
    local_ips = {"127.0.0.1", "::1"}
    try:
        local_name = socket.gethostname()
        for res in socket.getaddrinfo(local_name, None):
            local_ips.add(res[4][0])
    except Exception:
        pass

    return not host_ips.isdisjoint(local_ips)<|return|>

def make_find_paths(find_paths):
    """
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns.  Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    """
    if find_paths is None:
        return []

    try:
        iterator = iter(find_paths)
    except TypeError as exc:
        raise TypeError(f"{find_paths!r} is not iterable") from exc

    transformed = []
    glob_pattern_re = re.compile(r"[*?[\\]")
    for path in iterator:
        if not isinstance(path, str):
            raise TypeError(f"Path fragment must be a string, got {type(path).__name__}")
        # Preserve any existing scheme prefix (e.g., 'pp:') or glob pattern.
        if ':' in path or glob_pattern_re.search(path):
            transformed.append(path)
        else:
            transformed.append(f"sh:**/*{path}*/**")
    return transformed<|return|>

def _resolve_string(matcher):
    '''
    Get the value from environment given a matcher containing a name and an optional default value.
    If the variable is not defined in environment and no default value is provided, an Error is raised.
    '''
    # Determine name and default from matcher
    if isinstance(matcher, (list, tuple)):
        if len(matcher) == 1:
            name = matcher[0]
            default = None
        elif len(matcher) == 2:
            name, default = matcher
        else:
            raise ValueError("matcher must contain one or two elements")
    else:
        raise TypeError("matcher must be a list or tuple")

    # Resolve the environment variable
    value = os.getenv(name)
    if value is not None:
        return value
    if default is not None:
        return default

    # No value and no default: raise
    raise KeyError(f"Environment variable {name!r} not set and no default provided")<|return|>

def _parse_image_ref(image_href: str) -> Tuple[str, str, bool]:
    """Parse an image href into composite parts.

    :param image_href: href of an image
    :returns: a tuple of the form (image_id, netloc, use_ssl)
    :raises ValueError:
    """
    if not isinstance(image_href, str):
        raise ValueError(f"image_href must be a string, got {type(image_href).__name__}")

    try:
        parsed = urllib.parse.urlparse(image_href)
    except Exception as exc:
        raise ValueError(f"Malformed image href: {image_href}") from exc

    if parsed.scheme not in ("http", "https"):
        raise ValueError(f"Image href must use http or https scheme: {image_href}")

    use_ssl = parsed.scheme == "https"
    netloc = parsed.netloc
    if not netloc:
        raise ValueError(f"Image href must contain a network location: {image_href}")

    image_id = parsed.path.lstrip("/")
    # If the path is empty and a query is provided, the query can be part of the identifier
    if not image_id and parsed.query:
        image_id = parsed.query
    if not image_id:
        raise ValueError(f"Image href must contain a valid image identifier: {image_href}")

    return (image_id, netloc, use_ssl)<|return|>

