def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file.
    Return the results as a tuple of:
        dict of configuration filename to corresponding parsed configuration,
        and sequence of logging.LogRecord instances containing any parse errors.
    '''
    import json, os, re
    try:
        import yaml
        yaml_available = True
    except Exception:
        yaml_available = False

    logger = logging.getLogger(__name__)
    errors = []
    configs = {}

    # Ensure we have a list
    if isinstance(config_filenames, (str, bytes)):
        config_filenames = [config_filenames]
    if overrides is None:
        overrides = {}

    def _load_file(fname):
        try:
            with open(fname, 'r', encoding='utf-8') as f:
                content = f.read()
        except Exception as e:
            record = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f'Error opening configuration file "{fname}": {e}',
                args=None,
                exc_info=e
            )
            return None, record

        # Determine parser by extension
        ext = os.path.splitext(fname)[1].lower()
        parsed = None
        err = None
        try:
            if ext in {'.yaml', '.yml'} and yaml_available:
                parsed = yaml.safe_load(content) or {}
            elif ext == '.json':
                parsed = json.loads(content)
            else:
                # Try JSON first
                parsed = json.loads(content)
        except Exception as e:
            err = e

        if err is not None:
            record = logging.LogRecord(
                name=logger.name,
                level=logging.ERROR,
                pathname=fname,
                lineno=0,
                msg=f'Error parsing configuration file "{fname}": {err}',
                args=None,
                exc_info=err
            )
            return None, record

        return parsed, None

    def _apply_overrides(cfg, overrides_dict):
        """Apply top‑level overrides to cfg."""
        for key, val in overrides_dict.items():
            if key in cfg:
                cfg[key] = val
        return cfg

    def _resolve_env_in_obj(obj):
        """Recursively replace ${VAR} placeholders in all string values."""
        if isinstance(obj, dict):
            return {k: _resolve_env_in_obj(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_resolve_env_in_obj(elem) for elem in obj]
        elif isinstance(obj, str):
            # Find ${VAR} patterns
            def replacer(match):
                var_name = match.group(1)
                return os.getenv(var_name, '')
            return re.sub(r'\${([^}]+)}', replacer, obj)
        else:
            return obj

    for fname in config_filenames:
        cfg, err = _load_file(fname)
        if err:
            errors.append(err)
            continue
        if cfg is None:
            # Unexpected but skip
            continue
        # Apply overrides
        cfg = _apply_overrides(cfg, overrides)
        # Resolve environment variables
        if resolve_env:
            cfg = _resolve_env_in_obj(cfg)
        configs[fname] = cfg

    return configs, errors
<|return|>

def force_string(obj):
    """
    This function returns the bytes object corresponding to ``obj``
    in case it is a string using UTF-8.
    """
    if isinstance(obj, str):
        return obj.encode('utf-8')
