def from_raw_values(cls, values):
    """Create a Bookmarks object from a list of raw bookmark string values.

    You should not need to use this method unless you want to deserialize
    bookmarks.

    :param values: ASCII string values (raw bookmarks)
    :type values: Iterable[str]
    """
    if values is None:
        raise ValueError("values must not be None")
    # Values should be an iterable of strings, but a single string is not valid
    if isinstance(values, (str, bytes)) or not hasattr(values, "__iter__"):
        raise TypeError("values must be an iterable of strings")
    cleaned = []
    for v in values:
        if not isinstance(v, str):
            raise TypeError(f"Each bookmark must be a string, got {type(v).__name__}")
        cleaned.append(v)
    # Try to construct using a constructor that accepts a ``values`` argument
    try:
        return cls(values=cleaned)
    except TypeError:
        # Fallback: create an instance and set its ``values``/``bookmarks`` attribute
        obj = cls()
        if hasattr(obj, "values"):
            obj.values = cleaned
        elif hasattr(obj, "bookmarks"):
            obj.bookmarks = cleaned
        else:
            # If no obvious attribute we store in a generic ``_raw_values`` slot
            setattr(obj, "_raw_values", cleaned)
        return obj<|return|>

def scale(self, other=None, recompute=False):
    """Compute or set scale (integral of the histogram).

    If *other* is ``None``, return scale of this histogram.
    If its scale was not computed before, it is computed and stored for subsequent use
    (unless explicitly asked to *recompute*).
    Note that after changing (filling) the histogram one must explicitly recompute the scale
    if it was computed before.

    If a float *other* is provided, rescale self to *other*.

    Histograms with scale equal to zero can't be rescaled.
    :exc:`.LenaValueError` is raised if one tries to do that.
    """
    # Determine the underlying data structure
    data = None
    if hasattr(self, 'data'):
        data = self.data
    elif hasattr(self, '_data'):
        data = self._data
    else:
        raise AttributeError("Histogram object has no data attribute")

    # Helper to compute integral
    def _compute_integral():
        if isinstance(data, dict):
            return sum(data.values())
        else:
            try:
                return sum(data)
            except TypeError as exc:
                raise TypeError("Unsupported data type for histogram integral") from exc

    if other is None:
        # Return the stored scale, recomputing if necessary
        if not hasattr(self, '_scale') or recompute:
            self._scale = _compute_integral()
        return self._scale

    # Rescaling branch
    if not isinstance(other, (int, float)):
        raise TypeError(f"Expected numeric value for target scale, got {type(other).__name__}")

    # Ensure current scale is available
    current = self.scale(recompute=recompute)
    if current == 0:
        raise ValueError("Histogram scale is zero, cannot rescale")

    factor = other / current
    # Apply scaling to the underlying data
    if isinstance(data, dict):
        new_data = {k: v * factor for k, v in data.items()}
    else:
        try:
            new_data = [v * factor for v in data]
        except TypeError as exc:
            raise TypeError("Unsupported data type for scaling operation") from exc

    # Store back the scaled data
    if hasattr(self, 'data'):
        self.data = new_data
    else:
        self._data = new_data

    # Update stored scale
    self._scale = other
    # No explicit return (None) is standard for setters
    return None<|return|>

def scale(self, other=None):
    """
    Get or set the scale of the graph.

    If *other* is ``None``, return the scale of this graph.

    If a numeric *other* is provided, rescale to that value.
    If the graph has unknown or zero scale,
    rescaling that will raise :exc:`~.LenaValueError`.

    To get meaningful results, graph's fields are used.
    Only the last coordinate is rescaled.
    For example, if the graph has *x* and *y* coordinates,
    then *y* will be rescaled, and for a 3-dimensional graph
    *z* will be rescaled.
    All errors are rescaled together with their coordinate.
    """
    import numbers

    # Getting the current scale
    if other is None:
        return getattr(self, "scale", None)

    # Validate that the new scale is a real number
    if not isinstance(other, numbers.Real):
        raise TypeError("Scale must be a numeric value; got %r" % (other,))

    current = getattr(self, "scale", None)
    if current is None or current == 0:
        raise LenaValueError("Cannot rescale: current scale is unknown or zero.")

    # Rescale the last coordinate in all data points
    factor = other / current
    data = getattr(self, "data", None)
    if data is not None:
        if isinstance(data, list):
            for point in data:
                if isinstance(point, (list, tuple)) and len(point) > 0:
                    # Modify a copy if the point is immutable
                    if isinstance(point, tuple):
                        point = list(point)
                        point[-1] *= factor
                        # replace in the original list if possible
                        idx = data.index(point)
                        data[idx] = tuple(point)
                    else:
                        point[-1] *= factor
        else:
            # If data is not a list, attempt to treat it as a single point
            if isinstance(data, (list, tuple)) and len(data) > 0:
                if isinstance(data, tuple):
                    data = list(data)
                    data[-1] *= factor
                    self.data = tuple(data)
                else:
                    data[-1] *= factor

    # Rescale the errors associated with the data
    errors = getattr(self, "errors", None)
    if errors is not None:
        if isinstance(errors, list):
            for err in errors:
                if isinstance(err, (list, tuple)) and len(err) > 0:
                    if isinstance(err, tuple):
                        err = list(err)
                        err[-1] *= factor
                        idx = errors.index(err)
                        errors[idx] = tuple(err)
                    else:
                        err[-1] *= factor
        else:
            if isinstance(errors, (list, tuple)) and len(errors) > 0:
                if isinstance(errors, tuple):
                    errors = list(errors)
                    errors[-1] *= factor
                    self.errors = tuple(errors)
                else:
                    errors[-1] *= factor

    # Update the scale attribute
    self.scale = other
    return self<|return|>

def verifyClass(iface, candidate, tentative=False):
    """Verify that the *candidate* might correctly provide *iface*.

    The function checks whether ``candidate`` implements all public, callable
    attributes defined on ``iface``.  It accepts either a class or an instance
    as *candidate*.  If ``tentative`` is ``False`` (the default) missing
    attributes raise an ``AttributeError``; if ``tentative`` is ``True`` the
    function simply returns ``False`` when a requirement is not met.
    """
    # Helper to collect public callable members defined directly on the interface
    def _public_callables(cls):
        return [
            name
            for name, val in vars(cls).items()
            if not name.startswith('_') and callable(val)
        ]

    # Determine the class of the candidate (in case an instance is given)
    candidate_cls = candidate if isinstance(candidate, type) else type(candidate)

    # Quick test: if candidate is a subclass of iface, it satisfies the contract
    try:
        if issubclass(candidate_cls, iface):
            return True
    except Exception:
        # ``iface`` may not be a class or ``candidate_cls`` may not be a class
        pass

    # Otherwise perform an attribute-based check
    missing = []
    for name in _public_callables(iface):
        if not hasattr(candidate_cls, name):
            missing.append(name)
            continue
        cand_val = getattr(candidate_cls, name)
        if not callable(cand_val):
            missing.append(name)

    if missing:
        if tentative:
            return False
        else:
            raise AttributeError(
                f"Candidate lacks required methods for interface "
                f"{iface.__name__}: {', '.join(missing)}"
            )
    return True<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair least frequently used."""
    if len(self) == 0:
        raise KeyError('dictionary is empty')
    # Pick the key with the lowest frequency if a frequency map exists
    if hasattr(self, '_freq') and isinstance(self._freq, dict):
        try:
            key = min(self._freq, key=lambda k: self._freq[k])
        except ValueError:
            # Fallback if frequency map is unexpectedly empty
            key = next(iter(self))
    else:
        key = next(iter(self))
    value = self[key]
    del self[key]
    if hasattr(self, '_freq') and key in self._freq:
        del self._freq[key]
    return key, value<|return|>

def popitem(self):
    """Remove and return the `(key, value)` pair most recently used."""
    if not self:
        raise KeyError('popitem(): dictionary is empty')
    return super().popitem(last=True)<|return|>

def _create_in_regex(self) -> Pattern:
    """Create the in-style parameter regular expression.

    Returns the in-style parameter regular expression (:class:`re.Pattern`).
    """
    import re

    # The regex will match an <in> element with optional attributes, but
    # will not consume beyond the closing '>' character. It is intentionally
    # lazy and non-greedy to allow nested structures on the same line.
    pattern_str = r'<in(?:(?!>).)*>'
    try:
        return re.compile(pattern_str)
    except re.error as exc:
        raise ValueError(f"Unable to compile in-style regex: {exc}")<|return|>

