def identify_request(request: RequestType):
    """Try to identify whether this is a Diaspora request.

    Try first public message. Then private message. The check if this is a legacy payload.
    """
    try:
        # 1. Public message: hints in GET params or explicit flag
        if getattr(request, "is_public", False):
            return True
        if request.method == "GET":
            # Check for a "message" query param (common for public posts)
            try:
                if "message" in getattr(request.args, "keys", lambda: [])():
                    return True
            except Exception:
                pass

        # 2. Private message: POST form or JSON containing a private flag
        if request.method == "POST":
            payload = None
            # Try JSON body first
            if getattr(request, "is_json", False):
                payload = getattr(request, "get_json", lambda silent=True: None)(silent=True)
            # Fallback to form data
            if payload is None and hasattr(request, "form"):
                payload = getattr(request, "form", None)
            if isinstance(payload, dict):
                if payload.get("private") or payload.get("is_private"):
                    return True
                # If an authentication token is present, assume it is private
                if request.headers.get("Authorization"):
                    return True

        # 3. Legacy payload: explicit legacy flag in JSON payload
        if request.method == "POST" and getattr(request, "is_json", False):
            legacy_data = getattr(request, "get_json", lambda silent=True: None)(silent=True)
            if isinstance(legacy_data, dict) and legacy_data.get("legacy") is True:
                return True

    except Exception:
        # Operate safely on malformed requests – just return False
        pass

    return False<|return|>

def identify_request(request: RequestType) -> bool:
    """Try to identify whether this is a Matrix request"""
    try:
        # Handle dict-like request objects
        if isinstance(request, dict):
            # Common pattern: a 'type' key with value 'matrix'
            if request.get("type") == "matrix":
                return True
            # Fallback: a key named 'matrix' present
            if "matrix" in request:
                return True

        # Handle objects with a `type` attribute
        if hasattr(request, "type") and getattr(request, "type") == "matrix":
            return True

        # Handle string requests (e.g., URL paths)
        if isinstance(request, str) and request.lower().startswith("/matrix"):
            return True

        return False
    except Exception:
        # In case of any unexpected attributes or types, assume not a Matrix request
        return False<|return|>

def fetch_content_type(url: str) -> Optional[str]:
    """
    Fetch the HEAD of the remote url to determine the content type.
    """
    try:
        # Create a request that uses the HEAD method.
        try:
            # Python 3.3+ supports the method argument.
            req = urllib.request.Request(url, method='HEAD')
        except TypeError:
            # For older Python versions, override get_method.
            req = urllib.request.Request(url)
            req.get_method = lambda: "HEAD"

        with urllib.request.urlopen(req, timeout=10) as response:
            # Retrieve the Content-Type header if present.
            content_type = response.headers.get("Content-Type")
            if content_type:
                # Strip any parameters (e.g., charset).
                return content_type.split(";")[0].strip()
    except Exception:
        # Any network or parsing error results in None
        return None
    return None<|return|>

def test_tag(tag: str) -> bool:
    """Test a word whether it could be accepted as a tag."""
    try:
        if not isinstance(tag, str):
            return False
        if not tag:
            return False
        # Reject any whitespace characters
        if any(c.isspace() for c in tag):
            return False
        # Allow only alphanumeric characters, hyphens, and underscores
        allowed = set("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_-")
        return all(c in allowed for c in tag)
    except Exception:
        return False<|return|>

def xml_children_as_dict(node):
    """Turn the children of node <xml> into a dict, keyed by tag name.

    This is only a shallow conversation - child nodes are not recursively processed.
    """
    if node is None:
        raise ValueError("node cannot be None")
    try:
        children = list(node)
    except Exception as exc:
        raise TypeError(f"Object of type {type(node).__name__} is not iterable and cannot be used as an XML node") from exc

    result = {}
    for child in children:
        tag = getattr(child, 'tag', None)
        if tag is None:
            continue  # Skip non-element children if any
        if tag in result:
            existing = result[tag]
            if isinstance(existing, list):
                existing.append(child)
            else:
                result[tag] = [existing, child]
        else:
            result[tag] = child

    return result<|return|>

def check_sender_and_entity_handle_match(sender_handle, entity_handle):
    """Ensure that sender and entity handles match.

    Basically we've already verified the sender is who they say when receiving the payload. However, the sender might
    be trying to set another author in the payload itself, since Diaspora has the sender in both the payload headers
    AND the object. We must ensure they're the same.
    """
    # Validate input types
    if not isinstance(sender_handle, str):
        raise TypeError(f"sender_handle must be a string, got {type(sender_handle).__name__}")
    if not isinstance(entity_handle, str):
        raise TypeError(f"entity_handle must be a string, got {type(entity_handle).__name__}")

    # None or empty string checks
    if not sender_handle:
        raise ValueError("sender_handle is empty or None")
    if not entity_handle:
        raise ValueError("entity_handle is empty or None")

    # Perform the match check
    if sender_handle != entity_handle:
        raise ValueError(
            f"Sender handle '{sender_handle}' does not match entity handle '{entity_handle}'. "
            "This may indicate tampering or a misconfigured payload."
        )

    return True<|return|>

def get_nodeinfo_well_known_document(url, document_path=None):
    """Generate a NodeInfo .well-known document.

    See spec: http://nodeinfo.diaspora.software

    :arg url: The full base url with protocol, ie https://example.com
    :arg document_path: Custom NodeInfo document path if supplied (optional)
    :returns: dict
    """
    # Basic validation of the base URL
    if not isinstance(url, str):
        raise TypeError("url must be a string")
    if not url.startswith(("http://", "https://")):
        raise ValueError("url must include a protocol (http:// or https://)")

    # Determine the full href for the nodeinfo resource
    if document_path is None:
        # Default path according to the NodeInfo spec
        document_path = f"{url.rstrip('/')}/.well-known/nodeinfo/2.0"
    else:
        # If a custom path is supplied, ensure it is a valid absolute URL
        if not isinstance(document_path, str):
            raise TypeError("document_path must be a string")
        # If the path is relative, prepend the base URL
        if not document_path.startswith(("http://", "https://")):
            document_path = f"{url.rstrip('/')}/{document_path.lstrip('/')}"

    # Construct the well‑known nodeinfo document
    nodeinfo = {
        "links": [
            {
                "rel": "http://nodeinfo.diaspora.software/ns/schema/2.0",
                "href": document_path
            }
        ]
    }

    return nodeinfo<|return|>

def parse_diaspora_webfinger(document: str) -> dict:
    """
    Parse Diaspora webfinger which is either in JSON format (new) or XRD (old).

    https://diaspora.github.io/diaspora_federation/discovery/webfinger.html
    """
    if not document or not isinstance(document, str):
        raise ValueError("Input must be a non-empty string")

    # Trim whitespace to decide format
    doc_strip = document.strip()
    # Try JSON first
    if doc_strip.startswith('{') or doc_strip.startswith('['):
        try:
            import json
            data = json.loads(doc_strip)
            # Normalize to dict structure
            if isinstance(data, list):
                # JSON-API style list, take first item
                data = data[0] if data else {}
            subject = data.get('subject')
            aliases = data.get('aliases', [])
            links = data.get('links', [])
            return {
                'subject': subject,
                'aliases': aliases,
                'links': links,
            }
        except Exception as e:
            # fall back to XRD parsing
            pass

    # Assume XRD (XML)
    try:
        import xml.etree.ElementTree as ET
        root = ET.fromstring(doc_strip)
        # Helper to strip namespace
        def tag_local_name(tag):
            return tag.split('}')[-1] if '}' in tag else tag
        subject_el = None
        aliases = []
        links = []
        for child in root:
            name = tag_local_name(child.tag)
            if name == 'Subject':
                subject_el = child.text.strip() if child.text else None
            elif name == 'Alias':
                if child.text:
                    aliases.append(child.text.strip())
            elif name == 'Link':
                rel = child.attrib.get('rel')
                type_attr = child.attrib.get('type')
                href = child.attrib.get('href')
                links.append({
                    'rel': rel,
                    'type': type_attr,
                    'href': href,
                })
        result = {
            'subject': subject_el,
            'aliases': aliases,
            'links': links,
        }
        return result
    except Exception as e:
        raise ValueError(f"Unable to parse webfinger document: {e}")<|return|>

def try_retrieve_webfinger_document(handle: str) -> Optional[str]:
    """
    Try to retrieve an RFC7033 webfinger document. Does not raise if it fails.
    """
    try:
        resource = urllib.parse.quote_plus(f"acct:{handle}")
        host = handle.split("@")[1] if "@" in handle else handle
        url = f"https://{host}/.well-known/webfinger?resource={resource}"
        with urllib.request.urlopen(url, timeout=10) as resp:
            if resp.status == 200:
                return resp.read().decode("utf-8")
    except Exception:
        # Suppress all errors: return None if anything fails
        pass
    return None<|return|>

