@classmethod
    def validate_from_content(cls, spec_content=None):
        """validates that spec (YAML) content has all required fields

        :param spec_content: content of spec file
        :raise IRValidatorException: when mandatory data
        is missing in spec file
        :return: Dictionary with data loaded from a spec (YAML) file
        """
        if spec_content is None:
            raise IRValidatorException("spec_content must be provided")

        # If a string of YAML is given, load it into a dict
        if isinstance(spec_content, str):
            try:
                import yaml  # assuming PyYAML is available
                data = yaml.safe_load(spec_content)
            except Exception as exc:
                raise IRValidatorException(f"Failed to parse YAML: {exc}")
        else:
            data = spec_content

        if not isinstance(data, dict):
            raise IRValidatorException("Spec content must resolve to a mapping (dict)")

        # Retrieve the class-specific required fields, if defined
        required_fields = getattr(cls, "REQUIRED_FIELDS", None)
        if required_fields:
            missing = [f for f in required_fields if f not in data]
            if missing:
                raise IRValidatorException("Missing required fields: " + ", ".join(missing))

        return data<|return|>

@classmethod
def validate_from_file(cls, yaml_file=None):
    """Loads & validates that a YAML file has all required fields

    :param yaml_file: Path to YAML file
    :raise IRValidatorException: when mandatory data is missing in file
    :return: Dictionary with data loaded from a YAML file
    """
    if not yaml_file:
        raise IRValidatorException("yaml_file is required but not provided")
    try:
        import yaml
        with open(yaml_file, 'r', encoding='utf-8') as f:
            data = yaml.safe_load(f)
    except FileNotFoundError as e:
        raise IRValidatorException(f"YAML file not found: {yaml_file}") from e
    except yaml.YAMLError as e:
        raise IRValidatorException(f"Error parsing YAML file {yaml_file}: {e}") from e
    if not isinstance(data, dict):
        raise IRValidatorException("YAML file did not contain a mapping (dictionary)")
    required = getattr(cls, 'REQUIRED_FIELDS', [])
    missing = [field for field in required if field not in data]
    if missing:
        raise IRValidatorException(f"Missing required fields in YAML file: {', '.join(missing)}")
    return data<|return|>

def _include_groups(self, parser_dict):
    """Resolves the include dict directive in the spec files."""
    if not isinstance(parser_dict, dict):
        raise TypeError(f"_include_groups expects a dict, got {type(parser_dict).__name__}")

    def _resolve(obj):
        if isinstance(obj, dict):
            # Handle special "include" key
            if set(obj.keys()) == {"include"}:
                include_key = obj["include"]
                if not isinstance(include_key, str):
                    raise ValueError(f"Include key must be a string, got {type(include_key).__name__}")
                if include_key not in parser_dict:
                    raise KeyError(f"Include key '{include_key}' not found in the parser dictionary")
                # Return a deep copy to avoid side‑effects
                return _resolve(parser_dict[include_key])
            # Recurse through all mapping items
            return {k: _resolve(v) for k, v in obj.items()}
        elif isinstance(obj, list):
            return [_resolve(item) for item in obj]
        else:
            # Primitive types are returned unchanged
            return obj

    try:
        resolved = _resolve(parser_dict)
    except Exception as exc:
        # Wrap any exception with a clear message for debugging
        raise RuntimeError(f"Failed to resolve include groups: {exc}") from exc

    return resolved<|return|>

def get_spec_defaults(self):
    """Resolve arguments' values from spec and other sources. """
    defaults = {}
    try:
        # Get spec dict if available
        spec = getattr(self, "spec", {})
        if isinstance(spec, dict):
            if "defaults" in spec:
                defs = spec["defaults"]
                if isinstance(defs, dict):
                    defaults.update(defs)

        # Merge any additional defaults that might be stored elsewhere
        try:
            extra = getattr(self, "_spec_defaults", {})
            if isinstance(extra, dict):
                defaults.update(extra)
        except Exception:
            # Silently ignore problems accessing extra defaults
            pass
    except Exception as exc:
        # Wrap unexpected errors so callers know something went wrong
        raise RuntimeError("Error resolving spec defaults: %s" % exc) from exc
    return defaults<|return|>

