def get_option_spec(self, command_name, argument_name):
        """Gets the specification for the specified option name. """

        # Validate input parameters
        if not isinstance(command_name, str) or not command_name:
            raise ValueError("command_name must be a non-empty string")
        if not isinstance(argument_name, str) or not argument_name:
            raise ValueError("argument_name must be a non-empty string")

        # Attempt to retrieve the command specification
        try:
            command_spec = self.commands[command_name]
        except Exception as exc:
            raise KeyError(f"Command '{command_name}' not found") from exc

        # Extract the options mapping or collection
        options = getattr(command_spec, 'options', None)
        if options is None and hasattr(command_spec, 'get'):
            options = command_spec.get('options')
        if options is None:
            raise KeyError(f"No options defined for command '{command_name}'")

        # Find the option specification by name
        option_spec = None
        if isinstance(options, dict):
            option_spec = options.get(argument_name)
        else:
            # Assume iterable of objects with identifying attributes
            for opt in options:
                try:
                    # Common attributes: name, short, long
                    if getattr(opt, 'name', None) == argument_name \
                       or getattr(opt, 'short', None) == argument_name \
                       or getattr(opt, 'long', None) == argument_name:
                        option_spec = opt
                        break
                except Exception:
                    continue

        if option_spec is None:
            raise KeyError(f"Option '{argument_name}' not found for command '{command_name}'")

        return option_spec<|return|>

def get_silent_args(self, args):
    """list of silenced argument

    :param args: The received arguments.
    :return: list, silenced argument names
    """
    # Defensive programming: if args is None or empty, return empty list
    if not args:
        return []

    silent = []

    # Handle dict-like arguments: mapping of argument name to value
    try:
        for key, value in args.items():
            if value is None or value is False or value == "":
                silent.append(key)
        return silent
    except AttributeError:
        # If args is not a dict, try interpreting it as an iterable of key/value pairs
        try:
            for item in args:
                if isinstance(item, (tuple, list)) and len(item) == 2:
                    key, value = item
                    if value is None or value is False or value == "":
                        silent.append(key)
                elif isinstance(item, dict):
                    for key, value in item.items():
                        if value is None or value is False or value == "":
                            silent.append(key)
            return silent
        except Exception:
            # If all else fails, raise a descriptive exception
            raise ValueError("Unsupported type for 'args': expected dict or iterable of key/value pairs")

    return silent<|return|>

def _get_conditionally_required_args(self, command_name, options_spec, args):
    """List arguments with ``required_when`` condition matched.

    :param command_name: the command name.
    :param options_spec:  the list of command spec options.
    :param args: the received input arguments
    :return: list, list of argument names with matched ``required_when``
        condition
    """
    required = []
    for opt in options_spec:
        # ``required_when`` can be a predicate, a boolean, or a list thereof
        cond = opt.get("required_when")
        if cond is None:
            continue
        try:
            if callable(cond):
                if cond(command_name, args):
                    required.append(opt["name"])
            elif isinstance(cond, (list, tuple)):
                for c in cond:
                    if callable(c) and c(command_name, args):
                        required.append(opt["name"])
                        break
            else:
                # any truthy value treats as required
                if cond:
                    required.append(opt["name"])
        except Exception:
            # ignore failures in custom condition functions
            continue
    return required<|return|>

def validate_length_args(self, args):
    """Check if value of arguments is not longer than length specified.

    :param args: The received arguments.
    """
    # Expected maximum lengths per argument name are expected to be provided
    # in an attribute `arg_lengths` of the instance as a mapping:
    #   {'arg_name': max_length, ...}
    # If not present, the method will silently skip checking for that argument.
    arg_lengths = getattr(self, 'arg_lengths', {})
    for name, value in args.items():
        max_len = arg_lengths.get(name)
        if max_len is None:
            continue  # no length constraint for this argument
        try:
            current_len = len(value)
        except TypeError:
            # Value has no length (e.g., None or non-iterable), skip check
            continue
        if current_len > max_len:
            raise ValueError(
                f"Argument '{name}' length {current_len} exceeds maximum allowed {max_len}"
            )<|return|>

def validate_choices_args(self, args):
    """Check if value of choice arguments is one of the available choices.

    :param args: The received arguments.
    """
    # Ensure args is a dictionary mapping argument names to values.
    if not isinstance(args, dict):
        raise TypeError(f"Argument `args` must be a dict, got {type(args).__name__}")

    # Retrieve the mapping of argument names to their allowed choices.
    # The attribute name may vary; try common possibilities.
    allowed_map = getattr(self, "choices", None)
    if allowed_map is None:
        allowed_map = getattr(self, "_choices", None)
    if allowed_map is None:
        # Nothing to validate against; nothing to do.
        return

    for name, value in args.items():
        # Skip validation for arguments that don't have defined choices.
        if name not in allowed_map:
            continue

        choices = allowed_map[name]
        # Normalize the choices to a set for fast membership checks.
        if not isinstance(choices, (list, tuple, set)):
            raise TypeError(f"Choices for argument `{name}` must be a sequence, got {type(choices).__name__}")

        choice_set = set(choices)

        # support single or multiple values
        values_to_check = value
        if isinstance(value, (list, tuple, set)):
            values_to_check = value
        else:
            values_to_check = (value,)

        for v in values_to_check:
            if v not in choice_set:
                raise ValueError(
                    f"Invalid value for argument `{name}`: {v!r}. "
                    f"Allowed values are: {sorted(choice_set)!r}"
                )<|return|>

def create_complex_argumet_type(self, subcommand, type_name, option_name,
                                    spec_option):
    """Build the complex argument type

    :param subcommand: the command name
    :param type_name: the complex type name
    :param option_name: the option name
    :param spec_option: option's specifications
    :return: the complex type instance
    """
    # Basic input validation
    if not isinstance(subcommand, str):
        raise TypeError("subcommand must be a string")
    if not isinstance(type_name, str):
        raise TypeError("type_name must be a string")
    if not isinstance(option_name, str):
        raise TypeError("option_name must be a string")
    if not isinstance(spec_option, (dict, list, tuple)):
        raise TypeError("spec_option must be a dictionary, list or tuple")

    # Build a simple representation of the complex type
    try:
        complex_type = {
            "subcommand": subcommand,
            "type_name": type_name,
            "option_name": option_name,
            # Deep‑copy or wrap spec_option to avoid accidental mutation
            "spec_option": spec_option if isinstance(spec_option, (list, tuple)) else dict(spec_option)
        }
    except Exception as exc:
        raise RuntimeError(f"Failed to build complex type: {exc}") from exc

    return complex_type<|return|>

def get_nested_custom_and_control_args(self, args):
        """Split input arguments to control nested and custom.

        Controls arguments: control the IR behavior. These arguments
            will not be put into the spec yml file
        Nested arguments: are used by the Ansible playbooks and will be put
            into the spec yml file.
        Custom arguments: Custom ansible variables to be used instead of the
            normal nested usage.

        :param args: the collected list of args.
        :return: (dict, dict): flat dicts (control_args, nested_args)
        """
        # Accept dict or list of tuples
        if isinstance(args, dict):
            flat_args = dict(args)  # copy to avoid mutating input
        elif isinstance(args, (list, tuple)):
            try:
                flat_args = dict(args)
            except Exception as exc:
                raise ValueError(f"Expected a dict or list of 2-tuples for args, got {type(args)!r}") from exc
        else:
            raise TypeError(f"Unsupported type for args: {type(args)!r}. Expected dict or list of pairs.")

        # Determine control argument names (if configured)
        control_keys = set()
        if hasattr(self, "control_arg_names"):
            # The attribute could be a set, list, tuple, or comma‑separated string
            attr = getattr(self, "control_arg_names")
            if isinstance(attr, (set, list, tuple)):
                control_keys = set(attr)
            elif isinstance(attr, str):
                # split on commas or whitespace
                control_keys = set(k.strip() for k in attr.replace(",", " ").split() if k.strip())
        # If no configuration, assume no control args (all nested)
        # Build control and nested dicts
        control_args = {}
        nested_args = {}
        for key, val in flat_args.items():
            if key in control_keys:
                control_args[key] = val
            else:
                nested_args[key] = val

        return control_args, nested_args<|return|>

@staticmethod
    def merge_extra_vars(vars_dict, extra_vars=None):
        """Extend ``vars_dict`` with ``extra-vars``.

        :param vars_dict: Dictionary to merge extra-vars into.
        :param extra_vars: Iterable of extra-vars. Each element can be a dictionary
                           or a two‑element sequence (key, value).

        :raises TypeError: If ``vars_dict`` is not a dictionary.
        :raises ValueError: If an element in ``extra_vars`` cannot be interpreted
                            as a mapping or a (key, value) pair.
        :return: The updated ``vars_dict``.
        """
        # Validate the target dictionary
        if not isinstance(vars_dict, dict):
            raise TypeError("vars_dict must be a dictionary")

        # Nothing to merge
        if not extra_vars:
            return vars_dict

        # Merge each element
        for item in extra_vars:
            if isinstance(item, dict):
                # Update with a dictionary
                vars_dict.update(item)
            elif isinstance(item, (list, tuple)):
                if len(item) == 2:
                    key, value = item
                    vars_dict[key] = value
                else:
                    raise ValueError(
                        f"Invalid tuple length for extra_var: {item!r}. "
                        "Expected a pair (key, value)."
                    )
            else:
                raise ValueError(
                    f"Unsupported type for extra_var: {item!r}. "
                    "Expected dict or (key, value) pair."
                )

        return vars_dict<|return|>

def ansible_playbook(ir_workspace, ir_plugin, playbook_path, verbose=None,
                     extra_vars=None, ansible_args=None):
    """Wraps the 'ansible-playbook' CLI.

     :param ir_workspace: An Infrared Workspace object represents the active
     :param ir_plugin: An Infrared Plugin object of the current plugin
     :param playbook_path: the playbook to invoke
     :param verbose: Ansible verbosity level
     :param extra_vars: dict. Passed to Ansible as extra-vars
     :param ansible_args: dict of ansible-playbook arguments to plumb down
         directly to Ansible.
    """
    import os
    import subprocess
    import json

    # Basic validation of inputs
    if ir_workspace is None:
        raise ValueError("ir_workspace must not be None")
    if ir_plugin is None:
        raise ValueError("ir_plugin must not be None")
    if not isinstance(playbook_path, str):
        raise TypeError("playbook_path must be a string")
    if extra_vars is not None and not isinstance(extra_vars, dict):
        raise TypeError("extra_vars must be a dictionary")
    if ansible_args is not None and not isinstance(ansible_args, dict):
        raise TypeError("ansible_args must be a dictionary")

    # Resolve the playbook path relative to the workspace if it's not absolute
    if not os.path.isabs(playbook_path):
        base_path = getattr(ir_workspace, "workspace_path", None) or getattr(ir_workspace, "path", None) or os.getcwd()
        playbook_path = os.path.abspath(os.path.join(base_path, playbook_path))

    # Build the command list
    cmd = ["ansible-playbook", playbook_path]

    # Add verbosity flags
    if isinstance(verbose, int) and verbose > 0:
        cmd.append("-" + "v" * min(verbose, 5))  # cap at -vvvvv

    # Add extra-vars
    if extra_vars:
        try:
            var_json = json.dumps(extra_vars, separators=(",", ":"))
        except Exception as exc:
            raise ValueError("extra_vars must be JSON serializable") from exc
        cmd += ["--extra-vars", var_json]

    # Add additional ansible args
    if ansible_args:
        for key, value in ansible_args.items():
            if not isinstance(key, str):
                raise TypeError("ansible_args keys must be strings")
            flag = key
            if not flag.startswith("-"):
                flag = f"--{flag}"
            if isinstance(value, bool):
                if value:  # include flag if True
                    cmd.append(flag)
                else:
                    continue  # skip if False
            elif value is None:
                continue
            else:
                cmd += [flag, str(value)]

    # Determine the working directory (workspace root if available)
    cwd = getattr(ir_workspace, "workspace_path", None) or getattr(ir_workspace, "path", None) or os.getcwd()

    # Execute the command
    try:
        result = subprocess.run(
            cmd,
            cwd=cwd,
            capture_output=True,
            text=True,
            check=False,
        )
        if result.returncode != 0:
            raise subprocess.CalledProcessError(
                result.returncode,
                cmd,
                output=result.stdout,
                stderr=result.stderr,
            )
    except FileNotFoundError:
        raise FileNotFoundError(
            "The 'ansible-playbook' command was not found. "
            "Ensure Ansible is installed and in your PATH."
        ) from None
    except subprocess.CalledProcessError as exc:
        # Provide a more helpful message while preserving the original error
        raise exc
    except Exception as exc:
        raise RuntimeError("An unexpected error occurred while running ansible-playbook") from exc

    return result<|return|>

def get_plugin_spec_flatten_dict(plugin_dir):
    """Creates a flat dict from the plugin spec

    :param plugin_dir: A path to the plugin's dir
    :return: A flatten dictionary contains the plugin's properties
    """
    import os
    import json

    # Determine spec file: try yaml first, then json
    spec_file = None
    for ext in ('.yaml', '.yml', '.json'):
        candidate = os.path.join(plugin_dir, 'plugin' + ext)
        if os.path.isfile(candidate):
            spec_file = candidate
            break
    if spec_file is None and os.path.isdir(plugin_dir):
        # fallback: check for any .yaml/.yml/.json files
        for filename in os.listdir(plugin_dir):
            if filename.lower().endswith(('.yaml', '.yml', '.json')):
                spec_file = os.path.join(plugin_dir, filename)
                break
    if spec_file is None:
        raise FileNotFoundError(f"No plugin spec file found in {plugin_dir}")

    try:
        with open(spec_file, 'r', encoding='utf-8') as f:
            if spec_file.endswith(('.yaml', '.yml')):
                try:
                    import yaml
                except ImportError as e:
                    raise RuntimeError("PyYAML is required to parse YAML spec files") from e
                spec_data = yaml.safe_load(f)
            else:  # json
                spec_data = json.load(f)
    except Exception as exc:
        raise RuntimeError(f"Failed to read or parse spec file {spec_file}") from exc

    if not isinstance(spec_data, dict):
        raise ValueError("Spec file does not contain a top-level JSON/YAML mapping")

    flat_dict = {}

    def _flatten(prefix, value):
        if isinstance(value, dict):
            for k, v in value.items():
                _flatten(f"{prefix}.{k}" if prefix else k, v)
        elif isinstance(value, list):
            for i, item in enumerate(value):
                _flatten(f"{prefix}.{i}" if prefix else str(i), item)
        else:
            flat_dict[prefix] = value

    _flatten('', spec_data)
    return flat_dict<|return|>

def inject_config(self):
    """Set the environment variable for config path, if it is undefined."""
    env_var = 'CONFIG_PATH'
    # Get current value if set
    try:
        current = os.getenv(env_var)
    except Exception:
        current = None
    # If not set, try to use an attribute on the instance that holds the path
    if not current:
        path = None
        if hasattr(self, 'config_path'):
            path = self.config_path
        elif hasattr(self, 'path'):
            path = self.path
        if path:
            os.environ[env_var] = path
<|return|>
